const RULES = {
  "mandatoryNotice": {
    "status": "TE_BEVESTIGEN",
    "text": "[VERPLICHTE WAARSCHUWINGSZIN — letterlijk overnemen van de Keuringsraad KOAG/KAG]",
    "note": "Laat geen AI-model deze zin formuleren. Haal de exacte Nederlandse formulering bij de Keuringsraad en vul hem hier één keer in. check.mjs eist letterlijke aanwezigheid zodra de status BEVESTIGD is."
  },
  "blockPatterns": [
    {
      "id": "A2-absoluut",
      "rule": "A2",
      "severity": "block",
      "why": "Absolute belofte over de uitkomst van een stoppoging.",
      "patterns": [
        "gegarandeerd",
        "guaranteed",
        "\\b100\\s?%",
        "altijd succes",
        "zeker stoppen",
        "je stopt sowieso",
        "werkt altijd",
        "always works"
      ],
      "instead": "Beschrijf het programma en het gedrag, niet de uitkomst: 'negentig dagen, één plan'."
    },
    {
      "id": "A3-bewijs",
      "rule": "A3",
      "severity": "block",
      "why": "Suggereert wetenschappelijk bewijs dat niet in het dossier zit.",
      "patterns": [
        "klinisch bewezen",
        "clinically proven",
        "wetenschappelijk bewezen",
        "scientifically proven",
        "uit onderzoek blijkt",
        "studies show",
        "bewezen effectief",
        "proven effective"
      ],
      "instead": "Laat bewijsclaims weg, of citeer letterlijk uit de goedgekeurde productinformatie."
    },
    {
      "id": "A3-statistiek",
      "rule": "A3",
      "severity": "block",
      "why": "Percentage of slagingskans in een claimzin.",
      "patterns": [
        "\\b\\d{1,3}\\s?%\\s*(meer|hoger|kans|succes|effectiever|success|more)",
        "(kans|slagingskans|success rate)\\s*van\\s*\\d{1,3}\\s?%",
        "\\b\\d\\s*(op|van)\\s*de\\s*\\d+\\s*(mensen|rokers|klanten)"
      ],
      "instead": "Geen cijfers over uitkomsten. Cijfers over het product (aantal doosjes, dagen, prijs) mogen wel."
    },
    {
      "id": "A6-veiligheid",
      "rule": "A6",
      "severity": "block",
      "why": "Veiligheidsclaim bij een geneesmiddel.",
      "patterns": [
        "geen bijwerkingen",
        "zonder bijwerkingen",
        "no side effects",
        "volkomen veilig",
        "helemaal veilig",
        "completely safe",
        "veilig voor iedereen",
        "safe for everyone",
        "geschikt voor iedereen"
      ],
      "instead": "Verwijs naar de bijsluiter. Zeg niets over veiligheid dat daar niet in staat."
    },
    {
      "id": "A4-vergelijking",
      "rule": "A4",
      "severity": "block",
      "why": "Vergelijkende reclame met andere geneesmiddelenmerken.",
      "patterns": [
        "beter dan nicorette",
        "beter dan nicotinell",
        "beter dan niquitin",
        "better than nicorette",
        "effectiever dan",
        "sterker dan de concurrent",
        "de beste nicotine",
        "nummer 1",
        "#1 ",
        "marktleider"
      ],
      "instead": "Beschrijf wat QUITTER is, niet wat een ander niet is."
    },
    {
      "id": "A1-genezing",
      "rule": "A1",
      "severity": "block",
      "why": "Claim over genezing of gezondheidsuitkomst buiten de indicatie.",
      "patterns": [
        "geneest",
        "genezing",
        "cures?\\b",
        "je longen herstellen",
        "verlengt je leven",
        "maakt je gezond",
        "wordt je longen"
      ],
      "instead": "Blijf bij de goedgekeurde indicatie: nicotinevervanging bij het stoppen met roken."
    },
    {
      "id": "A5-aanbeveling",
      "rule": "A5",
      "severity": "block",
      "why": "Aanbeveling door beroepsbeoefenaren of bekende personen.",
      "patterns": [
        "aanbevolen door (artsen|dokters|apothekers|huisartsen)",
        "recommended by doctors",
        "onze arts",
        "artsen adviseren",
        "apothekers kiezen",
        "bekend van tv"
      ],
      "instead": "Laat de aanbeveling weg. Feitelijke informatie over registratie en fabrikant mag wel."
    },
    {
      "id": "A9-urgentie",
      "rule": "A9",
      "severity": "block",
      "why": "Kunstmatige schaarste of tijdsdruk bij een geneesmiddel.",
      "patterns": [
        "op\\s?=\\s?op",
        "laatste kans",
        "nog maar \\d+ (uur|stuks|dagen)",
        "mis het niet",
        "don't miss out",
        "alleen vandaag",
        "only today",
        "bijna uitverkocht"
      ],
      "instead": "Geen urgentie. Het aanbod is een programma van negentig dagen, geen uitverkoop."
    },
    {
      "id": "A7-minderjarigen",
      "rule": "A7",
      "severity": "block",
      "why": "Uiting die zich op minderjarigen richt.",
      "patterns": [
        "voor tieners",
        "for teens",
        "op school",
        "jongeren vanaf 1[0-7]",
        "scholieren"
      ],
      "instead": "Het product is uitsluitend voor 18 jaar en ouder."
    }
  ],
  "warnPatterns": [
    {
      "id": "A3-percentage",
      "rule": "A3",
      "severity": "warn",
      "why": "Elk percentage in een geneesmiddelenuiting moet onderbouwd zijn. Prijs- en productcijfers mogen, uitkomstcijfers niet.",
      "patterns": [
        "\\b\\d{1,3}\\s?%"
      ],
      "instead": "Gaat het over de werking of over stoppen: weglaten. Gaat het over prijs of btw: laat de compliance-agent het bevestigen."
    },
    {
      "id": "A8-cadeau",
      "rule": "A8",
      "severity": "warn",
      "why": "Cadeau of premie gekoppeld aan de aankoop van een geneesmiddel. Raakt de ZERO-constructie.",
      "patterns": [
        "gratis bij aankoop",
        "cadeau bij",
        "free gift",
        "krijg je gratis",
        "gratis erbij",
        "ontvang gratis"
      ],
      "instead": "Presenteer ZERO als onderdeel van het programma dat al betaald is, niet als premie erbovenop. Laat dit toetsen."
    },
    {
      "id": "A2-superlatief",
      "rule": "A2",
      "severity": "warn",
      "why": "Superlatief zonder onderbouwing.",
      "patterns": [
        "de beste",
        "the best",
        "revolutionair",
        "revolutionary",
        "uniek in nederland",
        "enige echte",
        "perfect"
      ],
      "instead": "Vervang door een concreet, controleerbaar feit."
    },
    {
      "id": "C1-privacy",
      "rule": "C1",
      "severity": "warn",
      "why": "Suggereert targeting op gezondheidsgedrag, wat met bijzondere persoonsgegevens niet mag.",
      "patterns": [
        "lookalike",
        "klantlijst uploaden",
        "retargeting van kopers",
        "customer list upload"
      ],
      "instead": "Gebruik geen klantdata voor targeting. Werk met interesse- en zoekintentie zonder gezondheidskenmerken."
    },
    {
      "id": "A1-belofte",
      "rule": "A1",
      "severity": "warn",
      "why": "Belofte over de uitkomst van stoppen, net buiten de indicatie.",
      "patterns": [
        "stop(t|pen)? je met roken",
        "maakt stoppen makkelijk",
        "makes quitting easy",
        "rookvrij in \\d+",
        "nooit meer roken"
      ],
      "instead": "Beschrijf het programma, niet het resultaat: 'een programma van negentig dagen'."
    }
  ],
  "channels": {
    "own_site": {
      "koagRequired": true,
      "notes": "Waarschuwingszin en EU-logo verplicht."
    },
    "email": {
      "koagRequired": true,
      "notes": "Geen gezondheidssegmentatie naar derden."
    },
    "search_ads": {
      "koagRequired": true,
      "notes": "Vooraf keuren; platformbeleid gezondheid."
    },
    "social_organic": {
      "koagRequired": true,
      "notes": "Zodra het product genoemd wordt, is het reclame."
    },
    "social_paid": {
      "koagRequired": true,
      "notes": "Beperkt door platformbeleid."
    },
    "influencer": {
      "koagRequired": true,
      "allowed": false,
      "notes": "Raakt A5 — niet doen."
    },
    "pr": {
      "koagRequired": false,
      "notes": "Gesponsorde artikelen zijn wél reclame."
    },
    "b2b": {
      "koagRequired": false,
      "notes": "Richting eindgebruiker gelden alle publieksregels alsnog."
    }
  }
};

// query komt binnen als JSON string: {"text": "...", "channel": "...", "isPublicAd": true}
let input;
try {
  input = typeof query === "string" ? JSON.parse(query) : query;
} catch (error) {
  input = { text: String(query), channel: null, isPublicAd: false };
}

const text = String(input.text || "");
const channel = input.channel || null;
const isPublicAd = Boolean(input.isPublicAd);
const findings = [];

function scan(list) {
  for (const entry of list) {
    for (const pattern of entry.patterns) {
      const regex = new RegExp(pattern, "gi");
      let match;
      while ((match = regex.exec(text)) !== null) {
        findings.push({
          id: entry.id,
          rule: entry.rule,
          severity: entry.severity,
          why: entry.why,
          instead: entry.instead,
          matched: match[0],
        });
        if (match.index === regex.lastIndex) regex.lastIndex += 1;
      }
    }
  }
}

scan(RULES.blockPatterns);
scan(RULES.warnPatterns);

if (isPublicAd) {
  const notice = RULES.mandatoryNotice;
  if (notice.status !== "BEVESTIGD") {
    findings.push({
      id: "B1-onbevestigd",
      rule: "B1",
      severity: "block",
      why: "De verplichte waarschuwingszin staat nog niet vast in rules.json.",
      instead: "Haal de exacte zin bij de Keuringsraad, vul rules.json en zet status op BEVESTIGD.",
      matched: "(status " + notice.status + ")",
    });
  } else if (!text.includes(notice.text)) {
    findings.push({
      id: "B1-waarschuwingszin",
      rule: "B1",
      severity: "block",
      why: "De verplichte waarschuwingszin ontbreekt letterlijk.",
      instead: "Neem letterlijk op: " + notice.text,
      matched: "(ontbreekt)",
    });
  }
  if (!/bijsluiter|leaflet|patient information/i.test(text)) {
    findings.push({
      id: "B3-bijsluiter",
      rule: "B3",
      severity: "block",
      why: "De aansporing om de bijsluiter te lezen ontbreekt.",
      instead: "Voeg de verwijzing naar de bijsluiter toe.",
      matched: "(ontbreekt)",
    });
  }
  if (!/nicotine/i.test(text)) {
    findings.push({
      id: "B2-werkzame-stof",
      rule: "B2",
      severity: "warn",
      why: "Het werkzame bestanddeel wordt niet genoemd.",
      instead: "Noem nicotine bij merknaam en sterkte.",
      matched: "(ontbreekt)",
    });
  }
  if (!/18\s*\+|18 jaar|18 and over/i.test(text)) {
    findings.push({
      id: "B6-leeftijd",
      rule: "B6",
      severity: "warn",
      why: "Geen leeftijdsvermelding (18+).",
      instead: "Vermeld 18 jaar en ouder.",
      matched: "(ontbreekt)",
    });
  }
}

const channelInfo = channel ? RULES.channels[channel] : null;
if (channelInfo && channelInfo.allowed === false) {
  findings.push({
    id: "D-kanaal-verboden",
    rule: "D",
    severity: "block",
    why: "Kanaal " + channel + " is voor QUITTER niet toegestaan. " + channelInfo.notes,
    instead: "Kies een ander kanaal.",
    matched: "",
  });
}

const blocks = findings.filter((f) => f.severity === "block");
const warns = findings.filter((f) => f.severity === "warn");
const verdict = blocks.length ? "BLOCK" : warns.length ? "PASS_MET_WAARSCHUWINGEN" : "PASS";

return JSON.stringify({
  verdict,
  koagRequired: channelInfo ? channelInfo.koagRequired : null,
  blocks,
  warns,
  note: "Deze poort vervangt geen jurist en geen Keuringsraad.",
}, null, 2);
